def can_partition_k(nums, k):
    total = sum(nums)
    if total % k:
        return False
    target = total // k
    nums = sorted(nums, reverse=True)
    if nums[0] > target:
        return False
    buckets = [0] * k
    def go(i):
        if i == len(nums):
            return True
        seen = set()
        for b in range(k):
            if buckets[b] + nums[i] <= target and buckets[b] not in seen:
                seen.add(buckets[b])
                buckets[b] += nums[i]
                if go(i + 1):
                    return True
                buckets[b] -= nums[i]
        return False
    return go(0)
